{
  "items": [
    {
      "title": "German General Social Survey (ALLBUS) 2023",
      "url_or_doi": "https://doi.org/10.4232/1.14544",
      "justification": "A nationally representative survey conducted in Germany in 2023 by GESIS. Covers social behaviour and attitudes, political attitudes, religion and values, social inequality, lifestyle, personality, employment, and demographic characteristics. Particularly useful for studying relationships between psychological characteristics, social conditions, and political or religious beliefs in Germany during the 2020s."
    },
    {
      "title": "German General Social Survey (ALLBUS) 2021",
      "url_or_doi": "https://doi.org/10.4232/1.14629",
      "justification": "Provides population survey data collected in Germany in 2021. Relevant to political behaviour and attitudes, social relationships, religion, values, social conditions, and demographic characteristics. Enables investigation of social attitudes and changes in German society during the COVID-19 period."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Cumulation 1980–2023",
      "url_or_doi": "https://doi.org/10.4232/1.14695",
      "justification": "A harmonized longitudinal collection of repeated cross-sectional surveys covering German society through 2023. Includes information on political attitudes, social behaviour, religion, values, employment, social inequality, environmental attitudes, and community identification. Particularly valuable for comparing observations from the 2020s with earlier decades."
    },
    {
      "title": "German General Social Survey (ALLBUScompact) – Cumulation 1980–2023",
      "url_or_doi": "https://doi.org/10.4232/1.14696",
      "justification": "A streamlined version of the ALLBUS cumulative survey dataset. Provides harmonized indicators of social attitudes, political preferences, religious affiliation, social conditions, and demographic characteristics. Useful for examining social change in Germany, including developments during the early 2020s."
    },
    {
      "title": "International Social Survey Programme (ISSP) 2020 – Environment IV",
      "url_or_doi": "https://doi.org/10.4232/1.14153",
      "justification": "An international survey dataset containing German observations collected in 2021. Directly relevant to natural environment, environmental conservation, environmental attitudes, and social values. Includes questions about environmental concerns, willingness to make economic sacrifices for environmental protection, environmental behaviour, and public perceptions of environmental problems. Supports comparisons between Germany and other countries."
    },
    {
      "title": "Environmental Awareness Study Germany 2024 (Umweltbewusstseinsstudie 2024)",
      "url_or_doi": "https://www.umweltbundesamt.de/themen/nachhaltigkeit-strategien-internationales/umweltbewusstsein-in-deutschland",
      "justification": "A representative survey conducted in autumn 2024 with approximately 2,500 respondents in Germany. Examines environmental awareness, climate change perceptions, environmental behaviour, conservation attitudes, and the relationship between environmental concerns and quality of life. The German Environment Agency provides links to survey data and supporting materials. Particularly relevant to natural environment, environment and conservation, psychology, and social attitudes."
    },
    {
      "title": "Environmental Awareness in Germany 2022",
      "url_or_doi": "https://www.umweltbundesamt.de/publikationen/umweltbewusstsein-in-deutschland-2022",
      "justification": "A representative German environmental awareness survey conducted in summer 2022 with approximately 2,000 participants. Covers climate protection, environmental behaviour, environmental engagement, sustainable economic transformation, and public perceptions of environmental problems. Provides survey results and accompanying statistical tables for studying environmental attitudes during the 2020s."
    },
    {
      "title": "Environmental Awareness in Germany 2024 – Scientific Study and Integrated Time-Series Data",
      "url_or_doi": "https://www.umweltbundesamt.de/publikationen/umweltbewusstseinsstudie-2024",
      "justification": "A German Environment Agency study examining environmental attitudes, climate adaptation, perceived health risks, quality of life, environmental behaviour, and social differences in environmental awareness. Its associated resources include an integrated time-series dataset supporting longitudinal comparisons. Especially suitable for research on environmental conservation, public values, and environmental psychology."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Tracking 2009–2026, Cumulation",
      "url_or_doi": "https://doi.org/10.4232/1.14820",
      "justification": "A cumulative German election survey dataset containing observations through March 2026. Covers political behaviour, party preferences, voting intentions, political interest, evaluations of political institutions, and political attitudes. Particularly valuable for studying changes in German political behaviour throughout the 2020s and relationships between political preferences and social characteristics."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Cross-Section 2025, Post-Election",
      "url_or_doi": "https://doi.org/10.4232/5.ZA10100.4.1.0",
      "justification": "A survey dataset examining political attitudes and electoral behaviour surrounding Germany's 2025 federal election. Provides information on voting decisions, political preferences, political participation, and characteristics of voters. Highly relevant to political behaviour and attitudes, political psychology, media-related political communication, and social divisions in contemporary Germany."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Data and Documentation",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "An official collection of German election research datasets, including surveys associated with the 2021 and 2025 federal elections and the 2024 European Parliament election. Provides access to cross-sectional surveys, panel studies, tracking surveys, and candidate studies. Relevant to political behaviour, voting, public opinion, political participation, and the relationship between media exposure and political attitudes."
    },
    {
      "title": "Socio-Economic Panel (SOEP-Core) – Data 1984–2024, Version 41",
      "url_or_doi": "https://www.diw-berlin.de/en/diw_01.c.997321.en/edition/",
      "justification": "One of Germany's principal longitudinal household surveys, containing annual observations through 2024. Covers employment, income, education, health, household circumstances, social conditions, and life satisfaction. Particularly relevant to employment, psychology, social indicators, consumption, and urban-rural differences. Its panel structure enables analysis of individual and household changes across the 2020s. Research data access is subject to the provider's conditions."
    },
    {
      "title": "German Time Use Survey 2022 (Zeitverwendungserhebung)",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Income-Consumption-Living-Conditions/Time-Use/_node.html",
      "justification": "An official German household survey conducted in 2022 that records daily activities through time-use diaries. Covers leisure, sport, media consumption, paid employment, unpaid work, shopping, travel time, childcare, and social activities. Particularly useful for investigating leisure, media, consumption behaviour, employment, gender differences, and social conditions. Aggregated results are publicly available, while microdata access is provided through the Federal Statistical Office's Research Data Centre."
    },
    {
      "title": "OECD Time Use Database – Germany 2022",
      "url_or_doi": "https://www.oecd.org/en/data/datasets/time-use-database.html",
      "justification": "An internationally harmonized dataset that includes German time-use observations from 2022. Measures time allocated to paid work, education, unpaid work, leisure, and personal care. Relevant to leisure, employment, social conditions, gender differences, and household behaviour. Particularly useful for comparing Germany with other OECD countries during the 2020s."
    },
    {
      "title": "BAuA Working Time Survey 2023 – Scientific Use File",
      "url_or_doi": "https://doi.org/10.48697/baua.azb23.suf.1",
      "justification": "A German employment survey dataset from the Federal Institute for Occupational Safety and Health. Covers working time arrangements and employment-related conditions among people working at least ten hours per week. Particularly relevant to employment, working conditions, occupational well-being, and relationships between work organization and social life. Provides a scientific-use dataset suitable for quantitative employment research."
    },
    {
      "title": "GENESIS-Online – German Federal Statistical Office Database",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/api-webservice.html",
      "justification": "The official statistical database maintained by Germany's Federal Statistical Office, with downloadable tables covering multiple years of the 2020s. Relevant statistical subjects include employment, population, consumption, tourism, environmental indicators, regional conditions, and socioeconomic development. Particularly suitable for combining national and regional indicators and examining urban-rural differences across Germany."
    },
    {
      "title": "GESIS Social Science Data Archive – German Survey Data",
      "url_or_doi": "https://www.gesis.org/en/services/finding-and-accessing-data/german-survey-data",
      "justification": "An official discovery portal providing access to multiple German social science survey programs, including ALLBUS, GLES, the GESIS Panel, and FReDA. Relevant research areas include political attitudes, psychology, social behaviour, religion, media, community life, employment, and social conditions. Useful for locating individual survey waves collected during the 2020s."
    },
    {
      "title": "GESIS Social Science Data Archive – Thematic Dataset Collections",
      "url_or_doi": "https://www.gesis.org/en/services/finding-and-accessing-data/browse",
      "justification": "A thematic discovery portal for research datasets covering Germany and other countries. Includes collections concerning elections and political attitudes, leisure and tourism, religion and spirituality, environmental attitudes, and social research. Provides access to datasets such as the International Social Survey Programme, European Values Study, and German population surveys. Useful for identifying additional German observations from the 2020s."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Data and Documentation",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "The official dataset catalogue for ALLBUS, including survey waves from 2021, 2023, and 2025. Covers political behaviour, religion, social values, social inequality, employment, personality, and other social attitudes. Provides access to individual survey datasets, questionnaires, variable documentation, and harmonized cumulative datasets. Particularly useful for locating variables relevant to several requested topics within a common survey framework."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Survey Programme",
      "url_or_doi": "https://www.gesis.org/en/gles",
      "justification": "An official German political research program providing longitudinal and cross-sectional datasets on voting behaviour, political attitudes, political participation, and electoral processes. Includes survey observations from multiple years of the 2020s. Its tracking and panel studies are particularly useful for analysing political psychology, electoral preferences, changes in political trust, and connections between social characteristics and political attitudes."
    },
    {
      "title": "German Environment Agency – Environmental Awareness Survey Data Collection",
      "url_or_doi": "https://www.umweltbundesamt.de/themen/nachhaltigkeit-strategien-internationales/umweltbewusstsein-in-deutschland",
      "justification": "An official collection of recurring German environmental awareness studies, including the 2020, 2022, and 2024 survey rounds. Provides access to survey data resources, statistical tables, and longitudinal comparisons. Particularly relevant to environmental conservation, climate-related attitudes, sustainable consumption, social values, and public perceptions of environmental risks."
    }
  ]
}
